INSTALL vgi FROM query_farm;
LOAD vgi FROM query_farm;

-- Attach a remote VGI worker as if it were a database
ATTACH 'earthquakes' AS earthquakes (
  TYPE vgi,
  LOCATION 'https://vgi-earthquakes.rusty-bb6.workers.dev'
);

INSTALL vgi FROM query_farm;
LOAD vgi FROM query_farm;

ATTACH 'earthquakes' AS earthquakes (
  TYPE vgi,
  LOCATION 'https://vgi-earthquakes.rusty-bb6.workers.dev'
);

SELECT time, mag, place
FROM earthquakes.main.recent
LIMIT 10;

